# Golden Dawn decan order, starting with Mars in the first decan of Aries.
PLANETS = ['Mars','Sun','Venus','Mercury','Moon','Saturn','Jupiter']
DECANS = {}
sequence = []
for sign in ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces']:
    for d in range(1,4):
        sequence.append((sign,d,PLANETS[len(sequence)%7]))
# Assign numbered minor cards 2-10 by suit and sign-triplet.
suit_signs = {
    'Wands':['Aries','Leo','Sagittarius'],
    'Cups':['Cancer','Scorpio','Pisces'],
    'Swords':['Libra','Aquarius','Gemini'],
    'Pentacles':['Capricorn','Taurus','Virgo'],
}
for suit, signs in suit_signs.items():
    for i, sign in enumerate(signs):
        for d in range(1,4):
            dec_idx = next(j for j, item in enumerate(sequence) if item[0] == sign and item[1] == d)
            DECANS[(suit, 2 + i*3 + d - 1)] = (sign,d,PLANETS[dec_idx % 7])

# Override from explicit sequence lookup is already correct; e.g. Mercury in Taurus for Five of Pentacles.

def slug(s):
    s=s.lower().replace('of ','')
    return re.sub(r'[^a-z0-9]+','_',s).strip('_')

rows=[]
for idx,(name,element,astro,up,rev,child,imagery,p1,p2) in enumerate(MAJORS):
    rows.append({
        'card_id':f'major_{idx:02d}_{slug(name)}','card_name':name,'arcana':'Major','suit':'Major Arcana','rank':idx,'element':element or '',
        'upright_keywords':up,'reversed_keywords':rev,'technical_upright':up+'. Use the image, question and spread position to refine the interpretation.',
        'technical_reversed':rev+'. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.',
        'child_explanation':child,'imagery_observation':imagery,'reflection_prompt_1':p1,'reflection_prompt_2':p2,
        'astrological_correspondence':astro,'correspondence_system':'Golden Dawn / traditional esoteric attribution; interpret within this system',
        'source_note':'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.'})

rank_num={'Ace':1,'Two':2,'Three':3,'Four':4,'Five':5,'Six':6,'Seven':7,'Eight':8,'Nine':9,'Ten':10,'Page':11,'Knight':12,'Queen':13,'King':14}
for suit,info in SUITS.items():
    for name,up,rev,tech,techrev,child,imagery,p1,p2 in info['cards']:
        rankword=name.split(' of ')[0]
        n=rank_num[rankword]
        element=info['element']
        if n==1:
            astro='Elemental attribution: '+element
            system='Golden Dawn / Book T suit-element attribution'
        elif 2 <= n <= 10:
            sign,d,planet=DECANS[(suit,n)]
            astro=f'{planet} in {sign} — decan {d} of 3'
            system='Golden Dawn / Book T decan attribution'
        else:
            formula={'King':f'Fire of {element}','Queen':f'Water of {element}','Knight':f'Air of {element}','Page':f'Earth of {element}'}[rankword]
            astro='Court elemental formula: '+formula+'; no single zodiac sign assigned in this base model'
            system='Golden Dawn court elemental formula; sign attribution intentionally omitted'
        rows.append({
            'card_id':f'{slug(suit)}_{n:02d}_{slug(name)}','card_name':name,'arcana':'Minor','suit':suit,'rank':n,'element':element,
            'upright_keywords':up,'reversed_keywords':rev,'technical_upright':tech,
            'technical_reversed':techrev,
            'child_explanation':child,'imagery_observation':imagery,'reflection_prompt_1':p1,'reflection_prompt_2':p2,
            'astrological_correspondence':astro,'correspondence_system':system,
            'source_note':'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.'})

# Order: Majors, then suit Ace-to-King.
fields=list(rows[0].keys())
with (DATA/'cards.csv').open('w',newline='',encoding='utf-8-sig') as f:
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)

